(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const state = () => JSON.stringify({
    url: location.href,
    radios: Array.from(document.querySelectorAll('input[type=radio]')).filter(i=>i.offsetParent!==null).map(i=>i.id+':'+i.checked).slice(0,6),
    otpVals: Array.from(document.querySelectorAll('input[type=number]')).filter(i=>i.offsetParent!==null && /^(first|second|third|fourth|fifth|sixth)$/.test(i.id||'')).map(i=>i.value),
    visBtns: Array.from(document.querySelectorAll('button')).filter(b=>b.offsetParent!==null).map(b=>(b.innerText||'').replace(/\s+/g,' ').trim()).filter(Boolean).filter(t=>/continue|confirm|otp|send|login/i.test(t)).slice(0,6),
    errs: (Array.from(document.querySelectorAll('div,span,p,label')).map(e=>(e.innerText||'').replace(/\s+/g,' ').trim()).filter(t=>/wrong|invalid|incorrect|expired|failed|mismatch|not found/i.test(t) && t.length<100).slice(0,3))
  });
  function setVal(el, v) {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(el, v);
    el.dispatchEvent(new Event('input', {bubbles:true}));
    el.dispatchEvent(new Event('change', {bubbles:true}));
  }
  let radioMsg = 'none';
  const rb = document.getElementById('clientId_rb');
  let rbChecked = false;
  if (rb) {
    rb.checked = true;
    rb.dispatchEvent(new Event('change', {bubbles:true}));
    try { rb.click(); } catch(e){}
    await sleep(800);
    rbChecked = rb.checked;
  }
  const ci = document.getElementById('fy_client_id');
  if (ci) setVal(ci, 'YA38754');
  await sleep(300);
  const cont = Array.from(document.querySelectorAll('button')).find(b => /^continue/i.test((b.innerText||'').replace(/\s+/g,' ').trim()) && b.offsetParent!==null);
  if (cont) cont.click();
  await sleep(8000);
  const boxes = Array.from(document.querySelectorAll('input[type=number]')).filter(i=>i.offsetParent!==null && /^(first|second|third|fourth|fifth|sixth)$/.test(i.id||''));
  if (boxes.length) {
    const digits = '978963';
    for (let i=0;i<boxes.length;i++) setVal(boxes[i], i < digits.length ? digits[i] : '');
    await sleep(400);
    const cfm = Array.from(document.querySelectorAll('button')).find(b => /confirm\s*otp/i.test((b.innerText||'').replace(/\s+/g,' ')) && b.offsetParent!==null);
    if (cfm) cfm.click();
    await sleep(9000);
  }
  return JSON.stringify({radioClientIdChecked: rbChecked, ...JSON.parse(state())});
})()
